#include "garden-capacity-audit.h"

std::optional<std::vector<std::pair<std::string,int>>> charm::v1n7::kindergarten_garden::audit_garden_capacity(const std::vector<charm::v1n7::kindergarten_garden::ChildPlot>& plots,const std::map<std::string,int>& capacity){for(const auto& c:capacity)if(c.first.empty()||c.second<0)return std::nullopt;std::set<std::string> children;std::map<std::string,int> totals;for(const auto& plot:plots){if(plot.child.empty()||!children.insert(plot.child).second)return std::nullopt;std::set<std::string> seen;for(const auto& p:plot.plants){if(p.plant.empty()||p.count<0||capacity.count(p.plant)==0||!seen.insert(p.plant).second)return std::nullopt;if(totals[p.plant]>std::numeric_limits<int>::max()-p.count)return std::nullopt;totals[p.plant]+=p.count;}}std::vector<std::pair<std::string,int>> out;for(const auto& p:totals)if(p.second>capacity.at(p.first))out.emplace_back(p.first,p.second-capacity.at(p.first));return out;}
